{-# LANGUAGE CApiFFI #-}

-- | Imports of the generated by-value shims (@include/tsffi_shims.h@,
-- DESIGN.md §5A.2). M0 imports one, which proves the generated header
-- compiles under @capi@; M4 imports the rest.
module TreeSitter.FFI.Shims (tsffiNodeIsNull) where

import Foreign.C.Types (CBool (..))
import Foreign.Ptr (Ptr)
import TreeSitter.FFI.Types (TSNode)

-- | @ts_node_is_null@, through its shim. @unsafe@: a node accessor.
foreign import capi unsafe "tsffi_shims.h tsffi_node_is_null"
  tsffiNodeIsNull :: Ptr TSNode -> IO CBool
